  `screenshots` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`screenshots`)),
  `lessons_learned` text DEFAULT NULL,
  `engineering_decisions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`engineering_decisions`)),
  `demo_url` varchar(255) DEFAULT NULL,
  `repository_url` varchar(255) DEFAULT NULL,
