INSERT INTO `projects` (`id`, `user_id`, `title`, `slug`, `tagline`, `problem`, `solution`, `architecture`, `tech_stack`, `screenshots`, `lessons_learned`, `engineering_decisions`, `demo_url`, `repository_url`, `status`, `published_at`, `ai_summary`, `ai_score`, `verification_status`, `verified_at`, `views_count`, `recognition_count`, `created_at`, `updated_at`) VALUES
(1, 6, 'Realtime Analytics Dashboard', 'realtime-analytics-dashboard-1', 'Live metrics streaming over WebSockets with sub-second latency.', 'Teams lacked a single pane of glass for live product metrics.', 'Built a realtime dashboard streaming events through Laravel Reverb into a reactive UI.', 'Event-sourced ingestion with a Redis stream, fan-out to WebSockets, and a Livewire island per widget.', '[\"PHP\",\"Laravel\",\"Livewire\",\"Redis\",\"Tailwind CSS\"]', NULL, 'Backpressure on the event bus and debouncing reconnects were the two biggest wins.', '[\"Chose PHP for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/0', 'published', '2026-07-21 08:33:59', NULL, NULL, 'pending', NULL, 342, 4, '2026-08-26 08:33:59', '2026-08-26 08:34:00'),
(2, 7, 'Open Source Package: Laravel Flags', 'open-source-package-laravel-flags-2', 'Feature flags with zero config and full audit trails.', 'Feature flags spread across config files and databases with no audit trail.', 'Publishable package providing flag evaluation, targeting rules, and an audit log.', 'A single flags table with JSON targeting, cached aggressively, invalidated on write.', '[\"PHP\",\"Laravel\",\"MySQL\"]', NULL, 'Cache invalidation is 95% of the job; the rest is DX.', '[\"Chose PHP for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/1', 'published', '2026-07-13 08:34:00', NULL, NULL, 'pending', NULL, 205, 2, '2026-08-26 08:34:00', '2026-08-26 08:34:00'),
(3, 8, 'CI Pipeline Optimizer', 'ci-pipeline-optimizer-3', 'Cut build times 40% with intelligent job scheduling.', 'Monorepo CI runs were taking 25+ minutes blocking merges.', 'Dependency-aware job scheduling that only runs affected packages.', 'Go service reading a build graph, scheduling on a custom runner pool with cached layers.', '[\"Go\",\"Docker\",\"CI\\/CD\"]', NULL, 'Leveraging Docker layer caching by topologically sorting jobs was the core insight.', '[\"Chose Go for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/2', 'published', '2026-07-13 08:34:00', NULL, NULL, 'pending', NULL, 109, 4, '2026-08-26 08:34:00', '2026-08-26 08:34:01'),
(4, 9, 'Design System Token Engine', 'design-system-token-engine-4', 'Tailwind-based tokens compiled at build time for every product.', 'Design tokens were drifting between design and engineering.', 'Single source-of-truth tokens generating Tailwind configs and CSS variables.', 'Token JSON → PostCSS plugin → framework-agnostic output consumed by 6 apps.', '[\"TypeScript\",\"Vite\",\"Tailwind CSS\"]', NULL, 'Start with a naming convention you can defend; everything else follows.', '[\"Chose TypeScript for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/3', 'published', '2026-06-29 08:34:01', NULL, NULL, 'pending', NULL, 260, 4, '2026-08-26 08:34:01', '2026-08-26 08:34:01'),
(5, 10, 'Knowledge Base with AI Summaries', 'knowledge-base-with-ai-summaries-5', 'Docs that summarize themselves and surface stale content.', 'Company wiki had thousands of pages with no freshness signal.', 'AI-generated summaries, staleness scoring, and a digest of outdated pages.', 'Background jobs generating summaries via LLM with graceful fallback, indexed for search.', '[\"PHP\",\"Laravel\",\"Livewire\",\"OpenAI\"]', NULL, 'Graceful fallback to rule-based summaries kept the feature alive when the AI was down.', '[\"Chose PHP for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/4', 'published', '2026-07-19 08:34:01', NULL, NULL, 'pending', NULL, 270, 3, '2026-08-26 08:34:01', '2026-08-26 08:34:01'),
(6, 11, 'Multi-tenant Billing Gateway', 'multi-tenant-billing-gateway-6', 'Subscription billing for a white-label SaaS platform.', 'Billing was per-customer bespoke, impossible to maintain.', 'Tenant-aware subscription engine with proration, trials, and webhook resilience.', 'Separate billing schema per tenant with a shared reconciliation worker.', '[\"PHP\",\"Laravel\",\"PostgreSQL\"]', NULL, 'Idempotent webhook handling is non-negotiable for payments.', '[\"Chose PHP for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/5', 'published', '2026-08-08 08:34:02', NULL, NULL, 'pending', NULL, 84, 3, '2026-08-26 08:34:02', '2026-08-26 08:34:02'),
(7, 12, 'Offline-First Mobile Companion', 'offline-first-mobile-companion-7', 'Field team app that syncs when connectivity returns.', 'Field teams lost hours of work when signal dropped in remote sites.', 'Offline-first sync engine with conflict resolution and optimistic UI.', 'Local SQLite store, mutation log, and a last-writer-wins sync protocol.', '[\"TypeScript\",\"React Native\",\"SQLite\"]', NULL, 'Designing the conflict model up front saved months of bug chasing.', '[\"Chose TypeScript for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/6', 'published', '2026-08-22 08:34:03', NULL, NULL, 'pending', NULL, 302, 3, '2026-08-26 08:34:03', '2026-08-26 08:34:03'),
(8, 13, 'Payroll Data Warehouse', 'payroll-data-warehouse-8', 'Petabyte-scale reporting over a decade of payroll history.', 'Payroll reporting ran overnight and broke on data volume.', 'Columnar warehouse with incremental loads and materialized dashboards.', 'Spark jobs landing Parquet into S3, queried through a SQL engine.', '[\"Python\",\"Spark\",\"AWS\"]', NULL, 'Incremental loads turned a nightly batch into a 10-minute job.', '[\"Chose Python for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/7', 'published', '2026-07-04 08:34:03', NULL, NULL, 'pending', NULL, 183, 3, '2026-08-26 08:34:03', '2026-08-26 08:34:03'),
(9, 14, 'Conversational Support Bot', 'conversational-support-bot-9', 'Resolves 60% of tier-1 tickets before a human sees them.', 'Support queue had 40% repeats that drained senior agents.', 'LLM-powered triage that answers known issues and routes the rest.', 'RAG over the help center with a confidence gate that escalates to humans.', '[\"PHP\",\"Laravel\",\"OpenAI\",\"Redis\"]', NULL, 'The confidence gate matters more than the model choice.', '[\"Chose PHP for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/8', 'published', '2026-08-06 08:34:03', NULL, NULL, 'pending', NULL, 39, 3, '2026-08-26 08:34:03', '2026-08-26 08:34:04'),
(10, 15, 'Edge CDN Cache Controller', 'edge-cdn-cache-controller-10', 'Purging and prewarming across 200 edge locations.', 'Cache invalidation was manual and took hours to propagate.', 'Control plane that fans out purge/prewarm commands to every edge.', 'Pub/sub command bus with per-edge acknowledgements and retries.', '[\"Go\",\"Kubernetes\",\"Redis\"]', NULL, 'At 200 nodes, fan-out design and observability are the whole job.', '[\"Chose Go for its ecosystem and hiring pool.\",\"Prioritized a boring, well-understood stack over novelty.\",\"Wrote integration tests around the risky 20% of the system.\"]', 'https://example.com', 'https://github.com/example/9', 'published', '2026-08-18 08:34:04', NULL, NULL, 'pending', NULL, 238, 3, '2026-08-26 08:34:04', '2026-08-26 08:34:04'),
