--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `headline` varchar(255) DEFAULT NULL,
  `bio` text DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `timezone` varchar(255) NOT NULL DEFAULT 'UTC',
  `github_url` varchar(255) DEFAULT NULL,
  `website_url` varchar(255) DEFAULT NULL,
  `linkedin_url` varchar(255) DEFAULT NULL,
  `experience_points` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `streak_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `two_hour_streak_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `two_hour_earned_xp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `longest_streak` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `last_activity_at` timestamp NULL DEFAULT NULL,
  `last_two_hour_reward_at` timestamp NULL DEFAULT NULL,
  `vouch_credits` int(10) UNSIGNED NOT NULL DEFAULT 3,
  `credit_balance` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `daily_evidence_count` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `daily_evidence_date` date DEFAULT NULL,
  `is_verified` tinyint(1) NOT NULL DEFAULT 0,
  `verified_at` timestamp NULL DEFAULT NULL,
  `verification_expires_at` timestamp NULL DEFAULT NULL,
  `short_domain` varchar(255) DEFAULT NULL,
  `auto_scan_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `auto_scan_active_until` timestamp NULL DEFAULT NULL,
  `last_auto_scan_at` timestamp NULL DEFAULT NULL,
  `is_admin` tinyint(1) NOT NULL DEFAULT 0,
  `billing_currency` varchar(8) DEFAULT NULL,
  `suspended_at` timestamp NULL DEFAULT NULL,
  `public_passport` tinyint(1) NOT NULL DEFAULT 1,
  `preferences` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`preferences`)),
  `feed_layout` varchar(255) NOT NULL DEFAULT 'list',
  `feature_requests_layout` varchar(255) NOT NULL DEFAULT 'list',
  `onboarding_completed_at` timestamp NULL DEFAULT NULL,
  `reputation_score` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `email` varchar(255) NOT NULL,
  `username` varchar(255) DEFAULT NULL,
  `avatar_path` varchar(255) DEFAULT NULL,
  `role` varchar(20) NOT NULL DEFAULT 'developer',
  `email_verified_at` timestamp NULL DEFAULT NULL,
